  1281  /** @brief Duplicates a matvar_t structure
  1282   *
  1283   * Provides a clean function for duplicating a matvar_t structure.
  1284   * @ingroup MAT
  1285   * @param in pointer to the matvar_t structure to be duplicated
  1286   * @param opt 0 does a shallow duplicate and only assigns the data pointer to
  1287   *            the duplicated array.  1 will do a deep duplicate and actually
  1288   *            duplicate the contents of the data.  Warning: If you do a shallow
  1289   *            copy and free both structures, the data will be freed twice and
  1290   *            memory will be corrupted.  This may be fixed in a later release.
  1291   * @returns Pointer to the duplicated matvar_t structure.
  1292   */
  1293  matvar_t *
  1294  Mat_VarDuplicate(const matvar_t *in, int opt)
  1295  {
  1296      matvar_t *out;
  1297      size_t i;
  1298
  1299      out = Mat_VarCalloc();
  1300      if ( out == NULL )
  1301          return NULL;
  1302
  1303      out->nbytes       = in->nbytes;
  1304      out->rank         = in->rank;
  1305      out->data_type    = in->data_type;
  1306      out->data_size    = in->data_size;
  1307      out->class_type   = in->class_type;
  1308      out->isComplex    = in->isComplex;
  1309      out->isGlobal     = in->isGlobal;
  1310      out->isLogical    = in->isLogical;
  1311      out->mem_conserve = in->mem_conserve;
  1312      out->compression  = in->compression;
  1313
  1314      if ( NULL != in->name ) {
  1315          size_t len = strlen(in->name) + 1;
  1316          out->name = (char*)malloc(len);
  1317          if ( NULL != out->name )
  1318              memcpy(out->name,in->name,len);
  1319      }
  1320
  1321      out->dims = (size_t*)malloc(in->rank*sizeof(*out->dims));
  1322      if ( out->dims != NULL )
  1323          memcpy(out->dims,in->dims,in->rank*sizeof(*out->dims));
