  1363                      out_sparse->njc = in_sparse->njc;
  1364                      out_sparse->jc = (mat_int32_t*)malloc(in_sparse->njc*sizeof(*out_sparse->jc));
  1365                      if ( out_sparse->jc != NULL )
  1366                          memcpy(out_sparse->jc, in_sparse->jc, in_sparse->njc*sizeof(*out_sparse->jc));
  1367                      out_sparse->ndata = in_sparse->ndata;
  1368                      if ( out->isComplex && NULL != in_sparse->data ) {
  1369                          out_sparse->data = malloc(sizeof(mat_complex_split_t));
